/* @autogenerated */
import { Component, computed, input, output, Signal } from '@angular/core';
import { Router } from '@angular/router';
import { configValue } from '@shared/context/config/app-config.service';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { MatIconModule } from '@angular/material/icon';
import { CommonModule } from '@angular/common';
import { MatToolbarModule } from '@angular/material/toolbar';
import { MatDividerModule } from '@angular/material/divider';
import { UserInfo } from '@shared/context/identity/user-info.model';
import { OfflineIndicatorComponent } from '@shared/toolkit/offline-sync/offline-indicator.component';
import { UserMenuItem } from 'app/bootstrap/workspace/workspace.model';
import { WorkspaceStateService } from 'app/bootstrap/workspace/workspace-state.service';

@Component({
  selector: 'app-toolbar',
  standalone: true,
  imports: [
    CommonModule,
    MatButtonModule,
    MatIconModule,
    MatToolbarModule,
    MatMenuModule,
    MatDividerModule,
    OfflineIndicatorComponent,
  ],
  templateUrl: './toolbar.component.html',
  styleUrl: './toolbar.component.scss',
})
export class ToolbarComponent {
  menuClicked = output<void>();
  user = input<UserInfo | null>();
  /** Inicial del nombre para el avatar. */
  initial = computed(() => (this.user()?.name ?? '').trim().charAt(0).toUpperCase());

  /** Opciones del workspace activo, antes de las genéricas; las que exigen un selector sin valor no se muestran. */
  readonly workspaceItems = computed<UserMenuItem[]>(() => {
    const contexts = this.appstate.contexts();
    return this.workspace
      .userMenu()
      .filter(
        (item) =>
          (item.requires ?? []).every((key) => present(contexts[key]?.value)) &&
          (item.except ?? []).every((key) => !present(contexts[key]?.value)),
      );
  });

  title: Signal<string | undefined>;
  accountUrl: Signal<string | undefined>;

  currentLanguage: Signal<string>;
  currentTenant: Signal<string>;

  public constructor(
    private readonly identity: IdentityService,
    private readonly appstate: AppStateService,
    private readonly workspace: WorkspaceStateService,
    private readonly router: Router,
  ) {
    this.title = configValue('meta.title');
    this.currentLanguage = appstate.language;
    this.currentTenant = appstate.tenant;
    this.accountUrl = configValue('identity.main.profile');
  }

  toogleMenu(): void {
    this.menuClicked.emit();
  }

  login(): void {
    this.identity.login('main');
  }

  logout(): void {
    this.identity.logout('main');
  }

  account(): void {
    let target = this.accountUrl()!;
    let tenant = this.currentTenant();
    if (tenant) {
      target = target.replace('{{tenant}}', tenant);
    }
    document.location = target;
  }

  /** Abre una opción del workspace: una URL externa, otro workspace o una ruta del activo. */
  open(item: UserMenuItem): void {
    if (item.url) {
      document.location = item.url;
    } else {
      this.router.navigate(this.workspace.link(item.route, item.workspace));
    }
  }
}

function present(value: unknown): boolean {
  return value !== undefined && value !== null && value !== '';
}
